import { Implementation } from './Implementation';
export class AppBlockGame {
    implementation: Implementation;
    host: HTMLElement;
    static Init(id: string) {
        const n = new AppBlockGame(id);
        n.Dummy();
    }
    constructor(id: string = 'SandBox') {
        const host = document.getElementById(id);

        const text = document.createElement('a')
        text.textContent = "https://namjulee.github.io/njs-lab-public/njslab-legacy/?demo=26"
        text.href = "https://namjulee.github.io/njs-lab-public/njslab-legacy/?demo=26"
        text.target='_blank'
        host.appendChild(text);

        if (host) {
            this.host = host;
            this.host.style.overflow = 'auto';
        }
        this.implementation = new Implementation(id);
    }
    Dummy() {
        //
    }
}

export class Solution {
    public divHost: HTMLElement;

    constructor(id: string, index = 0) {
        this.divHost = document.getElementById(id) as HTMLDivElement;

        const div = document.createElement('div');
        div.id ='block-game';
        div.style.width = '100%';
        div.style.height = '100%';
        this.divHost.appendChild(div);

        AppBlockGame.Init(div.id);
    }
    public destroy() {
        try {
            while (this.divHost !== undefined && this.divHost.lastElementChild !== undefined) {
                this.divHost.removeChild(this.divHost.lastElementChild);
            }
        } catch (error) { console.debug(error) }
    }
}